INSERT INTO `products` (`slug`, `name`, `tagline`, `format`, `gluten_free`, `bestseller`, `image`, `gallery`, `description`, `ingredients`, `usage_instructions`, `shelf_life`, `in_stock`, `stock_left`, `rating`, `reviews`, `created_at`, `updated_at`) VALUES ('traditional-idli-podi', 'Vismaya Traditional Idli Podi', 'Artisanal Wood-Roasted Gunpowder with Pure Hing & Lentils', 'vismaya', 0, 1, '/products/traditional-idli-podi/img-1.jpg', '[\"/products/traditional-idli-podi/img-1.jpg\",\"/products/traditional-idli-podi/img-2.jpg\",\"/products/traditional-idli-podi/img-3.jpg\",\"/products/traditional-idli-podi/img-4.jpg\"]', 'Grandmother\'s heritage recipe of slow-roasted urad dal, chana dal, sun-dried Guntur chillies, fresh curry leaves, and a generous pinch of authentic Y.G compounded hing. Coarsely ground for the signature crunchy texture that pairs exquisitely with hot idlis, crispy dosas, and cold-pressed sesame oil or ghee.', 'Urad Dal, Chana Dal, Dry Red Chillies, White Sesame, Curry Leaves, Y.G Compounded Asafoetida, Rock Salt.', 'Mix 1-2 tbsp with cold-pressed gingelly (sesame) oil or hot melted A2 ghee as a dip for idlis and dosas.', '9 months from packing. Keep jar sealed.', 1, NULL, 4.7, 260, 1791796459932, 1791623659932) ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `in_stock` = VALUES(`in_stock`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `product_variants` (`id`, `product_slug`, `label`, `price`, `mrp`, `stock`, `sort_order`) VALUES ('200g', 'traditional-idli-podi', '200 g', 135, 160, 110, 0) ON DUPLICATE KEY UPDATE `price` = VALUES(`price`), `mrp` = VALUES(`mrp`), `stock` = VALUES(`stock`);
