INSERT INTO `products` (`slug`, `name`, `tagline`, `format`, `gluten_free`, `bestseller`, `image`, `gallery`, `description`, `ingredients`, `usage_instructions`, `shelf_life`, `in_stock`, `stock_left`, `rating`, `reviews`, `created_at`, `updated_at`) VALUES ('kodo-pongal-mix', 'Vismaya Kodo Pongal Mix', 'Nutrient-Dense Wholesome Foxtail & Kodo Millet Breakfast Blend', 'vismaya', 1, 1, '/products/millet-pongal-mix/img-1.jpg', '[\"/products/millet-pongal-mix/img-1.jpg\",\"/products/millet-pongal-mix/img-2.jpg\"]', 'A hearty, low-glycemic traditional South Indian breakfast blend combining unpolished heritage Kodo and Foxtail millets with yellow moong dal, crushed Tellicherry black pepper, cumin seeds, roasted cashews, and ginger. Cooks into a piping-hot, comforting Ven Pongal in under 10 minutes.', 'Kodo Millet (Varagu), Foxtail Millet (Thinai), Yellow Moong Dal, Crushed Black Pepper, Cumin Seeds, Whole Cashews, Ginger, Curry Leaves, Y.G Pure Hing, Salt.', 'Pressure cook 1 cup mix with 3.5 cups water for 3 whistles, or simmer in a pot. Top with 1 spoon hot ghee.', '9 months from packing.', 1, NULL, 4.5, 178, 1792142059932, 1791623659932) ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `in_stock` = VALUES(`in_stock`), `updated_at` = VALUES(`updated_at`);
