INSERT INTO `store_settings` (`setting_key`, `setting_value`, `updated_at`) VALUES ('settings', '{\"siteName\":\"Y.G Asafoetida\",\"tagline\":\"Authentic Tirunelveli Stone-Compounded Hing Since 1932\",\"currency\":\"INR\",\"currencySymbol\":\"₹\",\"freeShippingThreshold\":499,\"standardShippingFee\":60,\"expressShippingFee\":99,\"maintenanceMode\":false,\"allowGuestCheckout\":true,\"enableStockAlerts\":true,\"supportPhone\":\"0462 - 233 5555\",\"salesMobile\":\"+91 7200622221\",\"social\":{\"instagram\":\"https://instagram.com/ygasafoetida\",\"facebook\":\"https://facebook.com/ygasafoetida\",\"youtube\":\"https://youtube.com/@ygasafoetida\",\"whatsapp\":\"https://wa.me/917200622221\"}}', 1792152261359) ON DUPLICATE KEY UPDATE `setting_value` = VALUES(`setting_value`);
INSERT INTO `store_settings` (`setting_key`, `setting_value`, `updated_at`) VALUES ('cms', '{\"announcement\":\"FREE SHIPPING ACROSS INDIA ON ORDERS ABOVE ₹499 · DIRECT FROM TIRUNELVELI WORKS\",\"hero\":{\"eyebrow\":\"Heritage Pure Compounded Hing · Estd. 1932\",\"title\":\"Stone-Compounded in Tirunelveli for Nine Decades\",\"subtitle\":\"Procured from alpine mountain roots, compounded on traditional granite rollers, and sealed fresh for authentic South Indian kitchens worldwide.\"},\"contact\":{\"companyName\":\"Mayil Agro Foods\",\"brandName\":\"Y.G Asafoetida\",\"addressLine1\":\"1/303, M.K. Nagar, near HP fuel station\",\"addressLine2\":\"Tenkasi - Tirunelveli Main Road\",\"city\":\"Tirunelveli\",\"pin\":\"627012\",\"state\":\"Tamil Nadu\",\"telephone\":\"0462 - 233 5555\",\"mobile\":\"+91 7200622221\",\"salesDesk\":\"+91 790 456 7979\",\"salesEmail\":\"sales@yghing.com\",\"exportEmail\":\"exports@yghing.com\",\"b2bEmail\":\"b2bsales@yghing.com\",\"supportEmail\":\"support@yghing.com\"},\"storyTimeline\":[{\"id\":\"1931\",\"chapterNo\":\"Chapter 01\",\"year\":\"1931\",\"category\":\"The Genesis\",\"title\":\"A Humble Beginning\",\"lead\":\"YG began in 1931 through our grandfather\'s initiative, procuring authentic Ferula oleoresin tears to establish culinary truth in Tirunelveli.\",\"quote\":\"Our journey began with a vision, dedication, and a commitment to quality.\",\"image\":\"/story/1931-founder.jpg\",\"alt\":\"Vintage illustration of the founder weighing pure spices on brass balance scales\"},{\"id\":\"1932\",\"chapterNo\":\"Chapter 02\",\"year\":\"1932\",\"category\":\"Brand Conception\",\"title\":\"The Birth of YG\",\"lead\":\"The business received the name YG, perfecting standardized hand-compounded recipes with stone mortar pits on South Car Street.\",\"quote\":\"Two letters that came to define genuine aromatic trust.\",\"image\":\"/logo.png\",\"alt\":\"Prominent YG logo treatment on archival seal\",\"isLogo\":true},{\"id\":\"1980\",\"chapterNo\":\"Chapter 03\",\"year\":\"1980\",\"category\":\"Formulation Breakthrough\",\"title\":\"Cake Powder\",\"lead\":\"A major milestone in the development of cake powder products, engineering controlled milling that preserved essential oils and delicate baking texture.\",\"image\":\"/story/1980-cake-powder.jpg\",\"alt\":\"Cake powder, a bowl of powder, and a freshly baked cake\"},{\"id\":\"1982\",\"chapterNo\":\"Chapter 04\",\"year\":\"1982\",\"category\":\"Pioneering Sachet\",\"title\":\"India\'s First Sachet\",\"lead\":\"Introduction of India\'s first sachet, according to our brand history, locking in fresh aromatic fragrance in affordable single-use packs.\",\"historicClaim\":true,\"image\":\"/story/1982-sachet.jpg\",\"alt\":\"Vintage 1982 YG sachet packaging on antique wood\"},{\"id\":\"2013\",\"chapterNo\":\"Chapter 05\",\"year\":\"2013\",\"category\":\"Third Generation\",\"title\":\"Third Generation Enters\",\"lead\":\"The third generation joined the business, continuing the family\'s entrepreneurial legacy while adopting international food safety standards.\",\"image\":\"/story/2013-generations.jpg\",\"alt\":\"Illustration showing generational connection and craft mentorship\"},{\"id\":\"2014\",\"chapterNo\":\"Chapter 06\",\"year\":\"2014\",\"category\":\"Category Research\",\"title\":\"Exploring Appalam\",\"lead\":\"The business began studying and exploring the Appalam category, stone-grinding urad dal flour blended with signature hing and sun-drying in open courtyards.\",\"image\":\"/story/2014-appalam.jpg\",\"alt\":\"Traditional sun-dried appalam discs in a heritage courtyard\"},{\"id\":\"2016\",\"chapterNo\":\"Chapter 07\",\"year\":\"2016\",\"category\":\"Wellness Expansion\",\"title\":\"Traditional Health Mix\",\"lead\":\"Formulating multigrain Sathu Maavu health mix made from slow-roasted indigenous millets, pulses, and nuts for daily family vitality.\",\"image\":\"/products/traditional-health-mix/img-1.jpg\",\"alt\":\"Traditional Health Mix Sathu Maavu packaging\"},{\"id\":\"2019\",\"chapterNo\":\"Chapter 08\",\"year\":\"2019\",\"category\":\"Ancient Grains\",\"title\":\"Ancient Millet Innovations\",\"lead\":\"Pioneering nutrient-dense traditional blends including multi-millet adai dosa mix, kodo pongal, and kodo sambar mixes.\",\"image\":\"/products/multi-millet-adai-dosa-mix/img-1.jpg\",\"alt\":\"Multi-millet adai dosa and grain mix\"},{\"id\":\"2025\",\"chapterNo\":\"Chapter 09\",\"year\":\"2025\",\"category\":\"Spice Heritage\",\"title\":\"Vismaya Rice Powders & Podis\",\"lead\":\"Launching the Vismaya culinary line of roasted paruppu podi, traditional idli podi, ellu podi, and nourishing moringa and pirandai podis.\",\"image\":\"/products/tirunelveli-special-paruppu-podi/img-1.jpg\",\"alt\":\"Vismaya authentic Tirunelveli paruppu podi\"},{\"id\":\"2026\",\"chapterNo\":\"Chapter 10\",\"year\":\"2026\",\"category\":\"Global Footprint\",\"title\":\"Ready-to-Cook & Worldwide Exports\",\"lead\":\"Reaching dinner tables and container ports across 30+ international markets with certified food safety and authentic South Indian culinary craft.\",\"image\":\"/products/all-product/img-1.jpg\",\"alt\":\"Complete heritage range and global export collection\"}]}', 1792152261360) ON DUPLICATE KEY UPDATE `setting_value` = VALUES(`setting_value`);
